25	template <typename GlobalData>
26	PTO_INTERNAL bool TGetAsyncIsFlatContiguous1D(GlobalData& globalData)
27	{
28	    const int shp0 = globalData.GetShape(GlobalTensorDim::DIM_0);
29	    const int shp1 = globalData.GetShape(GlobalTensorDim::DIM_1);
30	    const int shp2 = globalData.GetShape(GlobalTensorDim::DIM_2);
31	    const int shp3 = globalData.GetShape(GlobalTensorDim::DIM_3);
32	    const int shp4 = globalData.GetShape(GlobalTensorDim::DIM_4);
33	
34	    const int step0 = globalData.GetStride(GlobalTensorDim::DIM_0);
35	    const int step1 = globalData.GetStride(GlobalTensorDim::DIM_1);
36	    const int step2 = globalData.GetStride(GlobalTensorDim::DIM_2);
37	    const int step3 = globalData.GetStride(GlobalTensorDim::DIM_3);
38	    const int step4 = globalData.GetStride(GlobalTensorDim::DIM_4);
39	
40	    const bool packedLayout = (step4 == 1) && (step3 == shp4) && (step2 == shp3 * step3) && (step1 == shp2 * step2) &&
41	                              (step0 == shp1 * step1);
42	    const bool oneDimLogical = (shp0 == 1 && shp1 == 1 && shp2 == 1 && shp3 == 1);
43	    return packedLayout && oneDimLogical;
44	}
45	
46	template <typename GlobalData>
47	PTO_INTERNAL uint32_t TGetAsyncGetTotalElemCount(GlobalData& globalData)
48	{
49	    const uint32_t d0 = static_cast<uint32_t>(globalData.GetShape(GlobalTensorDim::DIM_0));
50	    const uint32_t d1 = static_cast<uint32_t>(globalData.GetShape(GlobalTensorDim::DIM_1));
51	    const uint32_t d2 = static_cast<uint32_t>(globalData.GetShape(GlobalTensorDim::DIM_2));
52	    const uint32_t d3 = static_cast<uint32_t>(globalData.GetShape(GlobalTensorDim::DIM_3));
53	    const uint32_t d4 = static_cast<uint32_t>(globalData.GetShape(GlobalTensorDim::DIM_4));
54	    return (((d0 * d1) * d2) * d3) * d4;
55	}
