57	template <typename GlobalDstData, typename GlobalSrcData>
58	PTO_INTERNAL bool TGetAsyncCheckTensorCompatibility()
59	{
60	    using SrcElem = typename GlobalSrcData::RawDType;
61	    static_assert(
62	        std::is_same_v<SrcElem, typename GlobalDstData::RawDType>, "TGET_ASYNC: src/dst element type mismatch");
63	    static_assert(GlobalSrcData::layout == GlobalDstData::layout, "TGET_ASYNC: src/dst layout mismatch");
64	    return true;
65	}
