67	template <typename GlobalDstData, typename GlobalSrcData>
68	PTO_INTERNAL AsyncEvent
69	TGET_ASYNC_SDMA_IMPL(GlobalDstData& dstGlobalData, GlobalSrcData& srcGlobalData, const AsyncSession& session)
70	{
71	    (void)TGetAsyncCheckTensorCompatibility<GlobalDstData, GlobalSrcData>();
72	
73	    PTO_ASSERT(
74	        dstGlobalData.data() != nullptr && srcGlobalData.data() != nullptr,
