21	PTO_INTERNAL void UpdateCachedPostDoneIds(uint64_t postId, uint64_t queueMask, SdmaRuntimeContext& runtimeCtx)
22	{
23	    uint32_t queue = 0U;
24	    while (queueMask != 0ULL) {
25	        if ((queueMask & 1ULL) != 0ULL && runtimeCtx.postDoneId[queue] < postId) {
26	            runtimeCtx.postDoneId[queue] = postId;
27	        }
28	        queueMask >>= 1U;
29	        ++queue;
30	    }
31	}
32	
33	PTO_INTERNAL bool CheckPostDoneIds(
34	    __gm__ uint8_t* postDoneBase, uint64_t postId, uint64_t queueMask, UbTmpBuf& tmpBuf, bool blocking)
35	{
36	    uint32_t queue = 0U;
37	    while (queueMask != 0ULL) {
38	        if ((queueMask & 1ULL) == 0ULL) {
39	            queueMask >>= 1U;
40	            ++queue;
41	            continue;
42	        }
43	        uint32_t attempts = 0U;
44	        while (GetValue<uint64_t>(GetPostDoneRecordAddr(postDoneBase, queue), tmpBuf) < postId) {
45	            if (!blocking || ++attempts >= kPostPollLimit) {
46	                return false;
47	            }
48	        }
49	        queueMask >>= 1U;
50	        ++queue;
51	    }
52	    return true;
53	}
54	
55	PTO_INTERNAL bool InitializeRuntimeCtx(const SdmaSession& session)
56	{
57	    SdmaRuntimeContext& runtimeCtx = session.runtimeCtx;
58	    const SdmaExecContext& execCtx = session.execCtx;
59	    if (execCtx.contextGm == nullptr || !IsValidTmpBuffer(execCtx.tmpBuf)) {
60	        return false;
61	    }
62	
63	    UbTmpBuf tmpBuf = execCtx.tmpBuf;
64	    runtimeCtx.postDoneBase = ResolvePostDoneBase(execCtx);
65	    if (runtimeCtx.postDoneBase == nullptr) {
66	        return false;
67	    }
68	    for (uint32_t queue = 0U; queue < execCtx.baseConfig.queue_num; ++queue) {
69	        SetValue<uint64_t>(GetPostDoneRecordAddr(runtimeCtx.postDoneBase, queue), tmpBuf, execCtx.syncId, 0ULL);
70	    }
71	    pipe_barrier(PIPE_ALL);
72	
73	    __gm__ BatchWriteChannelInfo* channelBase =
74	        reinterpret_cast<__gm__ BatchWriteChannelInfo*>(execCtx.contextGm + sizeof(BatchWriteFlagInfo));
75	    __gm__ BatchWriteChannelInfo* channels = channelBase + execCtx.channelGroupIdx * execCtx.baseConfig.queue_num;
76	    // ChannelInfo is populated outside AI Core and read through scalar loads during Post.
77	    // Invalidate stale metadata once at session build time to keep DCCI out of the Post hot path.
78	    __asm__ __volatile__("");
79	    dcci((__gm__ void*)channels, cache_line_t::ENTIRE_DATA_CACHE);
80	    __asm__ __volatile__("");
81	    dsb(DSB_DDR);
82	    for (uint32_t queue = 0U; queue < execCtx.baseConfig.queue_num; ++queue) {
83	        __gm__ BatchWriteChannelInfo* channel = channels + queue;
84	        const uint64_t packedHeadTail = GetValue<uint64_t>((__gm__ uint8_t*)channel, tmpBuf);
85	        runtimeCtx.sqHead[queue] = static_cast<uint32_t>(packedHeadTail);
86	        runtimeCtx.sqTail[queue] = static_cast<uint32_t>(packedHeadTail >> 32U);
87	    }
88	    return true;
89	}
90	
91	PTO_INTERNAL bool StoreFlagPayload(
92	    uint64_t postId, uint32_t queueCount, __gm__ uint8_t* flagPayload, const SdmaSession& session, UbTmpBuf& tmpBuf)
93	{
94	    SdmaRuntimeContext& runtimeCtx = session.runtimeCtx;
95	    if (postId > kFlagPayloadDepth) {
96	        // Post IDs are contiguous, so this slot was last used by postId - depth.
97	        // Wait for that flag source to be consumed before overwriting the slot.
98	        const uint64_t oldPostId = postId - kFlagPayloadDepth;
99	        const uint32_t slot = static_cast<uint32_t>(postId % kFlagPayloadDepth);
100	        const uint64_t oldQueueMask = QueueCountToMask(runtimeCtx.flagPayloadQueueCount[slot]);
101	        bool knownComplete = true;
102	        uint64_t remaining = oldQueueMask;
103	        uint32_t queue = 0U;
104	        while (remaining != 0ULL) {
105	            if ((remaining & 1ULL) != 0ULL && runtimeCtx.postDoneId[queue] < oldPostId) {
106	                knownComplete = false;
107	                break;
108	            }
109	            remaining >>= 1U;
110	            ++queue;
111	        }
112	        if (!knownComplete) {
113	            if (!CheckPostDoneIds(runtimeCtx.postDoneBase, oldPostId, oldQueueMask, tmpBuf, true)) {
114	                return false;
115	            }
116	            UpdateCachedPostDoneIds(oldPostId, oldQueueMask, runtimeCtx);
117	        }
118	    }
119	
120	    *reinterpret_cast<volatile __gm__ uint64_t*>(flagPayload) = postId;
121	    __asm__ __volatile__("" ::: "memory");
122	    runtimeCtx.flagPayloadQueueCount[postId % kFlagPayloadDepth] = static_cast<uint8_t>(queueCount);
123	    return true;
124	}
125	
126	PTO_INTERNAL bool ValidateSinglePostSqCapacity(
127	    __gm__ BatchWriteChannelInfo* channels, const SdmaConfig& config, uint32_t dataQueueCount, uint32_t postQueueCount)
128	{
129	    for (uint32_t queue = 0U; queue < postQueueCount; ++queue) {
130	        uint32_t dataSqes = 0U;
131	        if (queue < dataQueueCount) {
132	            dataSqes = (config.iter_num - 1U - queue) / config.queue_num + 1U;
133	        }
134	        const uint32_t sqesPerPost = dataSqes + 1U;
135	        const uint32_t sqDepth = channels[queue].sq_depth;
136	        if (sqDepth == 0U || sqesPerPost > sqDepth) {
137	            return false;
138	        }
139	    }
140	    return true;
141	}
142	
143	PTO_INTERNAL void SubmitDataTransferSqes(
144	    __gm__ BatchWriteChannelInfo* channels, __gm__ uint8_t* recvBuffer, __gm__ uint8_t* sendBuffer, uint64_t opcode,
145	    const SdmaConfig& config, SdmaRuntimeContext& runtimeCtx)
146	{
147	    for (uint32_t index = 0U; index < config.iter_num; ++index) {
148	        const uint32_t queue = index % config.queue_num;
149	        uint32_t transferBytes = static_cast<uint32_t>(config.block_bytes);
150	        if (index + 1U == config.iter_num) {
151	            transferBytes = static_cast<uint32_t>(config.per_core_bytes - index * config.block_bytes);
152	        }
153	        __gm__ uint8_t* src = sendBuffer + config.comm_block_offset + index * config.block_bytes;
154	        __gm__ uint8_t* dst = recvBuffer + config.comm_block_offset + index * config.block_bytes;
155	        AddOneMemcpySqe(
156	            channels + queue, src, dst, opcode, transferBytes, runtimeCtx.sqTail[queue],
157	            runtimeCtx.sqTail[queue] - runtimeCtx.sqHead[queue]);
158	        runtimeCtx.sqTail[queue] = (runtimeCtx.sqTail[queue] + 1U) % channels[queue].sq_depth;
159	    }
160	    pipe_barrier(PIPE_ALL);
161	}
162	
163	PTO_INTERNAL void RingDoorbell(
164	    __gm__ BatchWriteChannelInfo* channel, uint32_t sqTail, UbTmpBuf& tmpBuf, uint32_t syncId)
165	{
166	#ifdef PTO_NPU_ARCH_A5
167	    SetValue<uint32_t>((__gm__ uint8_t*)channel->sq_reg_base, tmpBuf, syncId, sqTail);
168	#else
169	    SetValue<uint32_t>((__gm__ uint8_t*)channel->sq_reg_base + 8U, tmpBuf, syncId, sqTail);
170	#endif
171	}
172	
173	PTO_INTERNAL void PublishDataTransferSqes(
174	    __gm__ BatchWriteChannelInfo* channels, uint32_t dataQueueCount, const uint32_t* sqTail, UbTmpBuf& tmpBuf,
175	    uint32_t syncId)
176	{
177	    __asm__ __volatile__("");
178	    dcci((__gm__ void*)channels->sq_base, cache_line_t::ENTIRE_DATA_CACHE);
179	    __asm__ __volatile__("");
180	    dsb(DSB_DDR);
181	    for (uint32_t queue = 0U; queue < dataQueueCount; ++queue) {
182	        RingDoorbell(channels + queue, sqTail[queue], tmpBuf, syncId);
183	    }
184	    pipe_barrier(PIPE_ALL);
185	}
186	
187	PTO_INTERNAL void SubmitFlagTransferSqes(
188	    __gm__ BatchWriteChannelInfo* channels, __gm__ uint8_t* flagPayload, uint32_t postQueueCount,
189	    SdmaRuntimeContext& runtimeCtx)
190	{
191	    for (uint32_t queue = 0U; queue < postQueueCount; ++queue) {
192	        AddOneMemcpySqe(
193	            channels + queue, flagPayload, GetPostDoneRecordAddr(runtimeCtx.postDoneBase, queue), 0U, kPostIdFlagBytes,
194	            runtimeCtx.sqTail[queue], runtimeCtx.sqTail[queue] - runtimeCtx.sqHead[queue]);
195	        runtimeCtx.sqTail[queue] = (runtimeCtx.sqTail[queue] + 1U) % channels[queue].sq_depth;
196	    }
197	    pipe_barrier(PIPE_ALL);
198	}
199	
200	PTO_INTERNAL void PersistSqTails(
201	    __gm__ BatchWriteChannelInfo* channels, uint32_t queueNum, const SdmaRuntimeContext& runtimeCtx, UbTmpBuf& tmpBuf,
202	    uint32_t syncId)
203	{
204	    for (uint32_t queue = 0U; queue < queueNum; ++queue) {
205	        const uint64_t packed = (static_cast<uint64_t>(runtimeCtx.sqTail[queue]) << 32U) | runtimeCtx.sqHead[queue];
206	        SetValue<uint64_t>((__gm__ uint8_t*)(channels + queue), tmpBuf, syncId, packed);
207	    }
208	    pipe_barrier(PIPE_ALL);
209	}
210	
211	PTO_INTERNAL void PublishFlagTransferSqes(
212	    __gm__ BatchWriteChannelInfo* channels, uint32_t beginQueue, uint32_t endQueue, const uint32_t* sqTail,
213	    UbTmpBuf& tmpBuf, uint32_t syncId)
214	{
215	    for (uint32_t queue = beginQueue; queue < endQueue; ++queue) {
216	        const uint32_t flagSqeIndex = (sqTail[queue] + channels[queue].sq_depth - 1U) % channels[queue].sq_depth;
217	        __gm__ BatchWriteItem* sqRing = reinterpret_cast<__gm__ BatchWriteItem*>(channels[queue].sq_base);
218	        __gm__ BatchWriteItem* flagSqe = sqRing + flagSqeIndex;
219	        __asm__ __volatile__("");
220	        dcci((__gm__ void*)flagSqe, cache_line_t::SINGLE_CACHE_LINE);
221	        __asm__ __volatile__("");
222	    }
223	    dsb(DSB_DDR);
224	    for (uint32_t queue = beginQueue; queue < endQueue; ++queue) {
225	        RingDoorbell(channels + queue, sqTail[queue], tmpBuf, syncId);
226	    }
227	    pipe_barrier(PIPE_ALL);
228	}
229	
230	struct SdmaPostState {
231	    __gm__ BatchWriteChannelInfo* channels;
232	    __gm__ uint8_t* flagPayload;
233	    UbTmpBuf tmpBuf;
234	    uint32_t dataQueueCount;
235	    uint32_t postQueueCount;
236	    uint64_t eventHandle;
237	};
238	
239	PTO_INTERNAL bool BeginSdmaPost(
240	    uint64_t messageLen, const SdmaSession& session, SdmaConfig& config, SdmaPostState& state)
241	{
242	    const SdmaExecContext& execCtx = session.execCtx;
243	    if (!session.valid || !BuildTransferConfig(execCtx.baseConfig, messageLen, config) || config.iter_num == 0U ||
244	        config.queue_num == 0U || config.queue_num > kPostMaxQueues ||
245	        execCtx.channelGroupIdx >= kSdmaMaxChannel / config.queue_num) {
246	        return false;
247	    }
248	    state.dataQueueCount = config.iter_num < config.queue_num ? config.iter_num : config.queue_num;
249	    __gm__ BatchWriteChannelInfo* channelBase =
250	        reinterpret_cast<__gm__ BatchWriteChannelInfo*>(execCtx.contextGm + sizeof(BatchWriteFlagInfo));
251	    state.channels = channelBase + execCtx.channelGroupIdx * config.queue_num;
252	    state.tmpBuf = execCtx.tmpBuf;
253	    SdmaRuntimeContext& runtimeCtx = session.runtimeCtx;
254	    state.postQueueCount =
255	        runtimeCtx.usedQueueCount > state.dataQueueCount ? runtimeCtx.usedQueueCount : state.dataQueueCount;
256	    if (!ValidateSinglePostSqCapacity(state.channels, config, state.dataQueueCount, state.postQueueCount) ||
257	        runtimeCtx.nextPostId >= kSdmaHandlePostIdMask) {
258	        return false;
259	    }
260	    const uint64_t postId = runtimeCtx.nextPostId + 1ULL;
261	    state.flagPayload = GetFlagPayloadAddr(ResolveFlagPayloadBase(execCtx), postId);
262	    if (!StoreFlagPayload(postId, state.postQueueCount, state.flagPayload, session, state.tmpBuf) ||
263	        !EncodeSdmaEventHandle(postId, state.postQueueCount, state.eventHandle)) {
264	        return false;
265	    }
266	    runtimeCtx.nextPostId = postId;
267	    runtimeCtx.usedQueueCount = state.postQueueCount;
268	    return true;
269	}
270	
271	PTO_INTERNAL AsyncEvent FinishSdmaPost(const SdmaConfig& config, const SdmaPostState& state, const SdmaSession& session)
272	{
273	    const SdmaExecContext& execCtx = session.execCtx;
274	    SdmaRuntimeContext& runtimeCtx = session.runtimeCtx;
275	    UbTmpBuf tmpBuf = state.tmpBuf;
276	    PublishDataTransferSqes(state.channels, state.dataQueueCount, runtimeCtx.sqTail, tmpBuf, execCtx.syncId);
277	    SubmitFlagTransferSqes(state.channels, state.flagPayload, state.postQueueCount, runtimeCtx);
278	    PersistSqTails(state.channels, config.queue_num, runtimeCtx, tmpBuf, execCtx.syncId);
279	    PublishFlagTransferSqes(state.channels, 0U, state.dataQueueCount, runtimeCtx.sqTail, tmpBuf, execCtx.syncId);
280	    if (state.dataQueueCount < state.postQueueCount) {
281	        PublishFlagTransferSqes(
282	            state.channels, state.dataQueueCount, state.postQueueCount, runtimeCtx.sqTail, tmpBuf, execCtx.syncId);
283	    }
284	    return AsyncEvent(state.eventHandle, DmaEngine::SDMA);
285	}
286	
287	PTO_INTERNAL AsyncEvent SdmaPostAsync(
288	    __gm__ uint8_t* recvBuffer, __gm__ uint8_t* sendBuffer, uint64_t opcode, uint64_t messageLen,
289	    const SdmaSession& session)
290	{
291	    if (recvBuffer == nullptr || sendBuffer == nullptr) {
292	        return {};
293	    }
294	    SdmaConfig config{};
295	    SdmaPostState state{};
296	    if (!BeginSdmaPost(messageLen, session, config, state)) {
297	        return {};
298	    }
299	    SubmitDataTransferSqes(state.channels, recvBuffer, sendBuffer, opcode, config, session.runtimeCtx);
300	    return FinishSdmaPost(config, state, session);
301	}
302	
303	PTO_INTERNAL bool SdmaEventCheck(uint64_t postId, uint64_t queueMask, const SdmaSession& session, bool blocking)
304	{
305	    if (!session.valid || postId == 0ULL || queueMask == 0ULL) {
306	        return false;
307	    }
308	    UbTmpBuf tmpBuf = session.eventCtx.tmpBuf;
309	    if (!CheckPostDoneIds(session.runtimeCtx.postDoneBase, postId, queueMask, tmpBuf, blocking)) {
310	        return false;
311	    }
312	    UpdateCachedPostDoneIds(postId, queueMask, session.runtimeCtx);
313	    return true;
314	}
315	
316	PTO_INTERNAL bool SdmaTestEvent(uint64_t handle, const SdmaSession& session)
317	{
318	    uint64_t postId = 0ULL;
319	    uint32_t queueCount = 0U;
320	    if (!DecodeSdmaEventHandle(handle, postId, queueCount)) {
321	        return false;
322	    }
323	    const uint64_t queueMask = QueueCountToMask(queueCount);
324	    return SdmaEventCheck(postId, queueMask, session, false);
325	}
326	
327	PTO_INTERNAL bool SdmaWaitEvent(uint64_t handle, const SdmaSession& session)
328	{
329	    uint64_t postId = 0ULL;
330	    uint32_t queueCount = 0U;
331	    if (!DecodeSdmaEventHandle(handle, postId, queueCount)) {
332	        return false;
333	    }
334	    const uint64_t queueMask = QueueCountToMask(queueCount);
335	    return SdmaEventCheck(postId, queueMask, session, true);
336	}
337	
338	} // namespace detail
339	} // namespace sdma
340	} // namespace comm
341	} // namespace pto
342	
343	#endif // PTO_COMM_ASYNC_SDMA_SDMA_ASYNC_DETAIL_POST_HPP
