193	    config.block_bytes = baseConfig.block_bytes;
194	    config.comm_block_offset = baseConfig.comm_block_offset;
195	    config.per_core_bytes = messageLen;
196	    config.iter_num = (config.per_core_bytes + config.block_bytes - 1) / config.block_bytes;
