200	PTO_INTERNAL void PrepareWorkspace(
201	    __gm__ uint8_t* workspace, const SdmaConfig& config, WorkspaceLayout& layout, uint32_t channelGroupIdx)
202	{
203	    const uint64_t perCoreRecvSize = static_cast<uint64_t>(config.queue_num) * kSdmaFlagLength;
204	    const uint64_t perGroupSendSize = static_cast<uint64_t>(config.queue_num) * kSdmaMinTransferBytes;
205	
206	    // Event workspace layout:
207	    // [send staging: kSdmaSendWorkspaceBytes — one 64B slot per queue per channel group]
208	    // [recv records: channelGroupIdx * (queue_num * kSdmaFlagLength)]
209	    __gm__ uint8_t* recvBase = workspace + kSdmaSendWorkspaceBytes;
210	    __gm__ uint8_t* myRecv = recvBase + static_cast<uint64_t>(channelGroupIdx) * perCoreRecvSize;
211	
212	    layout.send_workspace = workspace + static_cast<uint64_t>(channelGroupIdx) * perGroupSendSize;
213	    layout.recv_workspace = myRecv;
